package doapp.juntos;
import org.json.*;
import java.util.*;
final class TelegramSetup {
 static final class SetupError extends Exception{SetupError(String text){super(text);}}
 final TelegramSync api;
 TelegramSetup(Store store,String token)throws Exception{if(!SetupRules.tokenValid(token))throw new SetupError("Pega el token completo que entrega BotFather.");api=new TelegramSync(store,store.config().put("token",token.trim()));}
 JSONObject bot()throws Exception{return api.request("getMe",new JSONObject()).getJSONObject("result");}
 LinkedHashMap<String,String> channels()throws Exception{JSONObject hook=api.request("getWebhookInfo",new JSONObject()).getJSONObject("result");if(!hook.optString("url").isEmpty())throw new SetupError("Este bot está conectado a otro servicio. Crea uno exclusivo para esta pareja o pega manualmente los enlaces de los mensajes; no se modificó su conexión actual.");JSONArray updates=api.request("getUpdates",new JSONObject().put("timeout",0).put("limit",100).put("allowed_updates",new JSONArray().put("channel_post").put("edited_channel_post").put("my_chat_member"))).getJSONArray("result");LinkedHashMap<String,String> found=new LinkedHashMap<>();for(int j=0;j<updates.length();j++){JSONObject u=updates.getJSONObject(j),post=u.optJSONObject("channel_post");if(post==null)post=u.optJSONObject("edited_channel_post");if(post==null)post=u.optJSONObject("my_chat_member");if(post!=null){JSONObject chat=post.optJSONObject("chat");if(chat!=null&&chat.optString("type").equals("channel"))found.put(chat.getString("id"),chat.optString("title","Canal"));}}return found;}
 JSONObject validate(String a,String b)throws Exception{if(a.equals(b))throw new SetupError("Seleccionaste el mismo canal dos veces. Crea un canal A y otro B diferentes.");JSONObject bot=bot();String botId=bot.getString("id");check(a,"A",botId);check(b,"B",botId);return bot;}
 void check(String id,String label,String botId)throws Exception{JSONObject chat;try{chat=api.request("getChat",new JSONObject().put("chat_id",id)).getJSONObject("result");}catch(TelegramSync.SyncError e){throw new SetupError("El bot no puede acceder al canal "+label+". Revisa su ID y añádelo como administrador de ese canal.");}if(!chat.optString("type").equals("channel"))throw new SetupError("El espacio "+label+" debe ser un canal de Telegram, no un grupo ni un chat.");if(!chat.optString("username").isEmpty())throw new SetupError("El canal "+label+" es público. Cambia su tipo a Privado para esta agenda.");JSONObject member=api.request("getChatMember",new JSONObject().put("chat_id",id).put("user_id",Long.parseLong(botId))).getJSONObject("result");if(!member.optString("status").equals("administrator"))throw new SetupError("Añade el bot como administrador del canal "+label+".");if(!member.optBoolean("can_post_messages")||!member.optBoolean("can_edit_messages"))throw new SetupError("En el canal "+label+", permite al bot publicar y editar mensajes. Después vuelve a comprobar.");}
}
